transforms.code:
	def buildElement(value, fontWeight, foreColor, bgColor):
#		system.perspective.print("%s %s %s %s"%(value, fontWeight, foreColor, bgColor))
		if (bgColor or None) is None: bgColor = '#FFFFFF'		
		style = {'backgroundColor': bgColor}
		if fontWeight is not None:	style.update({"fontWeight": fontWeight})		
		if foreColor is not None: style.update({"color": foreColor})
		else: style.update({"color": system.kanoa.utilities.getContrastingColor(bgColor)})
		style.update({'borderColor': bgColor or '#000000', 'borderRadius': '4px', 'margin': '1px'})	
		return {'value': value, 'style':style}

	lotOperations = system.kanoa.utilities.convertDatasetToJSON(value)
	for lotOperation in lotOperations:
		lotOperation['lotOperationName'] = buildElement(lotOperation['lotOperationName'], None, None, lotOperation['lotOperationColor'])
		lotOperation['lastUpdated'] = '%s by %s'%(system.date.format(lotOperation['changedDate'] or lotOperation['createdDate'], 'YY-MM-dd HH:mm'), lotOperation['changedByUser'] or lotOperation['createdByUser'])

	return lotOperations

