customMethods.script:

for row in self.view.custom.assetLinks.selectedData:
	if system.kanoa.lot.unlinkLotOperationAsset(row['lotOperationAssetLinkId'], self.view.custom.security.userId) == 'Disabled': 
		system.perspective.sendMessage('showWarningToast', {'message': '%s link has been disabled as there are historical entries asssociated with this lot operation.'%row['lotOperationName']})

self.view.refreshBinding("custom.assetLinks.data")

return


for row in self.view.custom.itemLinks.selectedData:
	retVal = system.kanoa.lot.unlinkLotOperationItem(row['lotOperationItemLinkId'], self.view.custom.security.userId)
	system.perspective.print("Calling unlinkLotOperationItem() with %s returned %s"%(row['lotOperationItemLinkId'], retVal))
	if retVal == 'Disabled': 
		system.perspective.sendMessage('showWarningToast', {'message': '%s link has been disabled as there are historical entries asssociated with this lot operation.'%row['lotOperationItemLinkId']})
	elif retVal != 'Deleted':
		system.perspective.sendMessage('showWarningToast', {'message': '%s %s '%(row['lotOperationItemLinkId'], retVal)})
	else:
		pass

self.view.refreshBinding("custom.itemLinks.data")

return


for row in self.view.custom.lotOperations.selectedData:
	retVal, msg = system.kanoa.lot.deleteLotOperation(row['lotOperationId'], self.view.custom.security.userId)
	if msg: system.perspective.sendMessage('showFailerToast', {'message': 'Lot Operation could not be deleted. %s'%msg})
	else: system.perspective.sendMessage('showSuccessfulToast', {'message': 'Lot Operation %s has been deleted'%row['lotOperationName']})

self.view.refreshBinding("custom.lotOperations.data")

return

messageHandlers.script:
#This is how we get the assets and items selected
system.perspective.print("updatePopupSelection msg rcvd")

if payload.has_key('msgHandler'):
	if payload['msgHandler'] == 'assetSelected': self.view.custom.assetIdList = [item['value']['assetId'] for item in payload['selection']]
	elif payload['msgHandler'] == 'itemSelected':
		itemIdList = []
		itemClassIdList = []
		for item in payload['selection']:
			if item['value'].has_key('itemId'):
				itemIdList.append(item['value']['itemId'])
			elif item['value'].has_key('path'):
				itemClassIdList.append(system.kanoa.utilities.getFieldValue('itemClassId', system.kanoa.item.getItemClasses({'itemClassPath': item['value']['path']})))

		self.view.custom.itemIdList = itemIdList
		self.view.custom.itemClassIdList = itemClassIdList

return
